/// The configuration parameters of Core (§3.6.2).
#[derive(Debug, Clone)]
pub struct Config {
}

/// A state of Core: one field per parameter.
#[derive(Debug, Clone)]
pub struct S {
    pub phase: Fun<Client, Phase>,
    pub queue: Vec<Client>,
    pub free: bool,
}

fn initial(config: &Config) -> Result<S, StepError> {
    Ok(S {
        phase: Fun::new(Phase::IDLE),
        queue: Vec::new(),
        free: true,
    })
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Event {
    Ask(Client),
    Release(Client),
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Action {
    Grant(Client),
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Entry {
    Event(Event),
    Action(Action),
}

// c_ask
fn match0(s: &S, a0: &Client) -> Result<Option<(Client, )>, StepError> {
    let v_c = a0.clone();
    if !((((&s.phase)).get(&v_c.clone()) == Phase::IDLE)) {
        return Ok(None);
    }
    Ok(Some((v_c, )))
}

fn fire0(s: &mut S, env: (Client, )) -> Result<(), StepError> {
    let (v_c, ) = env;
    let mut o_phase = Ov::over(&s.phase);
    o_phase.set(v_c.clone(), Phase::WAITING);
    let w_phase = o_phase.writes();
    let n_queue = rt::snoc(std::mem::take(&mut s.queue), v_c.clone());
    for (k, v) in w_phase {
        s.phase.set(k, v);
    }
    s.queue = n_queue;
    Ok(())
}

// c_release
fn match1(s: &S, a0: &Client) -> Result<Option<(Client, )>, StepError> {
    let v_c = a0.clone();
    if !((((&s.phase)).get(&v_c.clone()) == Phase::HOLDING)) {
        return Ok(None);
    }
    Ok(Some((v_c, )))
}

fn fire1(s: &mut S, env: (Client, )) -> Result<(), StepError> {
    let (v_c, ) = env;
    let mut o_phase = Ov::over(&s.phase);
    o_phase.set(v_c.clone(), Phase::IDLE);
    let w_phase = o_phase.writes();
    let n_free = true;
    for (k, v) in w_phase {
        s.phase.set(k, v);
    }
    s.free = n_free;
    Ok(())
}

// c_grant
fn match2(s: &S, a0: &Client) -> Result<Option<(Client, )>, StepError> {
    let v_c = a0.clone();
    if !((s.free.clone() && (!(s.queue).is_empty() && (v_c.clone() == rt::head_ref(&s.queue)?)))) {
        return Ok(None);
    }
    Ok(Some((v_c, )))
}

fn fire2(s: &mut S, env: (Client, )) -> Result<(), StepError> {
    let (v_c, ) = env;
    let mut o_phase = Ov::over(&s.phase);
    o_phase.set(v_c.clone(), Phase::HOLDING);
    let w_phase = o_phase.writes();
    let n_free = false;
    let n_queue = rt::tail(std::mem::take(&mut s.queue))?;
    for (k, v) in w_phase {
        s.phase.set(k, v);
    }
    s.queue = n_queue;
    s.free = n_free;
    Ok(())
}

/// Checks the action record against the unrefined Core (docs/spec.md §3.8.9).
#[derive(Debug)]
pub struct Acceptor {
    s: S,
}

impl Acceptor {
    pub fn new(config: Config) -> Result<Acceptor, StepError> {
        Ok(Acceptor { s: initial(&config)? })
    }

    /// The state, for tests.
    pub fn state(&self) -> &S {
        &self.s
    }

    /// The state, for tests that start from another initial state.
    #[doc(hidden)]
    pub fn state_mut(&mut self) -> &mut S {
        &mut self.s
    }

    pub fn accept(&mut self, entry: &Entry) -> Result<(), Reject> {
        match entry {
            Entry::Action(Action::Grant(a0)) => {
                let e2 = match2(&self.s, a0).map_err(Reject::Step)?;
                let found = [e2.is_some()].iter().filter(|x| **x).count();
                if found > 1 {
                    return Err(Reject::Ambiguous);
                }
                if let Some(env) = e2 {
                    return fire2(&mut self.s, env).map_err(Reject::Step);
                }
                Err(Reject::Rejected)
            }
            Entry::Event(Event::Ask(a0)) => {
                let e0 = match0(&self.s, a0).map_err(Reject::Step)?;
                let found = [e0.is_some()].iter().filter(|x| **x).count();
                if found > 1 {
                    return Err(Reject::Ambiguous);
                }
                if let Some(env) = e0 {
                    return fire0(&mut self.s, env).map_err(Reject::Step);
                }
                Err(Reject::Rejected)
            }
            Entry::Event(Event::Release(a0)) => {
                let e1 = match1(&self.s, a0).map_err(Reject::Step)?;
                let found = [e1.is_some()].iter().filter(|x| **x).count();
                if found > 1 {
                    return Err(Reject::Ambiguous);
                }
                if let Some(env) = e1 {
                    return fire1(&mut self.s, env).map_err(Reject::Step);
                }
                Err(Reject::Rejected)
            }
        }
    }
}

fn enc_Client(v: &Client, out: &mut Vec<u8>) {
    codec::nat(match v {
        Client::c1 => 0,
        Client::c2 => 1,
        Client::c3 => 2,
    }, out);
}

fn dec_Client(r: &mut codec::Rd<'_>) -> Result<Client, DecodeError> {
    match r.nat()? {
        0 => Ok(Client::c1),
        1 => Ok(Client::c2),
        2 => Ok(Client::c3),
        _ => Err(DecodeError("a constructor index")),
    }
}

fn enc_Phase(v: &Phase, out: &mut Vec<u8>) {
    codec::nat(match v {
        Phase::IDLE => 0,
        Phase::WAITING => 1,
        Phase::HOLDING => 2,
    }, out);
}

fn dec_Phase(r: &mut codec::Rd<'_>) -> Result<Phase, DecodeError> {
    match r.nat()? {
        0 => Ok(Phase::IDLE),
        1 => Ok(Phase::WAITING),
        2 => Ok(Phase::HOLDING),
        _ => Err(DecodeError("a constructor index")),
    }
}

/// The bytes of an entry (docs/spec.md §3.8.10).
pub fn encode(entry: &Entry, out: &mut Vec<u8>) {
    match entry {
        Entry::Event(Event::Ask(a0)) => {
            out.push(0);
            codec::nat(0, out);
            enc_Client(a0, out);
        }
        Entry::Event(Event::Release(a0)) => {
            out.push(0);
            codec::nat(1, out);
            enc_Client(a0, out);
        }
        Entry::Action(Action::Grant(a0)) => {
            out.push(1);
            codec::nat(0, out);
            enc_Client(a0, out);
        }
    }
}

/// The entry of some bytes (§3.8.10).
pub fn decode(bytes: &[u8]) -> Result<Entry, DecodeError> {
    let mut r = codec::Rd { b: bytes, p: 0 };
    let r = &mut r;
    let side = r.byte()?;
    let code = r.nat()?;
    let e = match (side, code) {
        (0, 0) => Entry::Event(Event::Ask(dec_Client(r)?)),
        (0, 1) => Entry::Event(Event::Release(dec_Client(r)?)),
        (1, 0) => Entry::Action(Action::Grant(dec_Client(r)?)),
        _ => return Err(DecodeError("a label")),
    };
    if !r.done() {
        return Err(DecodeError("trailing bytes"));
    }
    Ok(e)
}

/// The indexes refreshed at the ids the last summand wrote, in ascending order
/// (docs/spec.md §3.8.3).
fn refresh(s: &mut S) -> Result<(), StepError> {
    Ok(())
}

fn stepper_init(s: &mut S) -> Result<(), StepError> {
    Ok(())
}

// c_ask
fn match_s0(s: &S, a0: &Client) -> Result<Option<(Client, )>, StepError> {
    let v_c = a0.clone();
    if !((((&s.phase)).get(&v_c.clone()) == Phase::IDLE)) {
        return Ok(None);
    }
    Ok(Some((v_c, )))
}

fn fire_s0(s: &mut S, env: (Client, )) -> Result<(), StepError> {
    let (v_c, ) = env;
    let mut o_phase = Ov::over(&s.phase);
    o_phase.set(v_c.clone(), Phase::WAITING);
    let w_phase = o_phase.writes();
    let n_queue = rt::snoc(std::mem::take(&mut s.queue), v_c.clone());
    for (k, v) in w_phase {
        s.phase.set(k, v);
    }
    s.queue = n_queue;
    Ok(())
}

// c_release
fn match_s1(s: &S, a0: &Client) -> Result<Option<(Client, )>, StepError> {
    let v_c = a0.clone();
    if !((((&s.phase)).get(&v_c.clone()) == Phase::HOLDING)) {
        return Ok(None);
    }
    Ok(Some((v_c, )))
}

fn fire_s1(s: &mut S, env: (Client, )) -> Result<(), StepError> {
    let (v_c, ) = env;
    let mut o_phase = Ov::over(&s.phase);
    o_phase.set(v_c.clone(), Phase::IDLE);
    let w_phase = o_phase.writes();
    let n_free = true;
    for (k, v) in w_phase {
        s.phase.set(k, v);
    }
    s.free = n_free;
    Ok(())
}

// c_grant
fn out0(s: &mut S, out: &mut Vec<Action>) -> Result<bool, StepError> {
    if !((s.free.clone() && !(s.queue).is_empty())) {
        return Ok(false);
    }
    #[cfg(feature = "firing")]
    FIRING.store(1, core::sync::atomic::Ordering::Relaxed);
    let act = Action::Grant(rt::head_ref(&s.queue)?);
    let mut o_phase = Ov::over(&s.phase);
    o_phase.set(rt::head_ref(&s.queue)?, Phase::HOLDING);
    let w_phase = o_phase.writes();
    let n_free = false;
    let n_queue = rt::tail(std::mem::take(&mut s.queue))?;
    for (k, v) in w_phase {
        s.phase.set(k, v);
    }
    s.queue = n_queue;
    s.free = n_free;
    out.push(act);
    Ok(true)
}

const OUTS: [fn(&mut S, &mut Vec<Action>) -> Result<bool, StepError>; 1] = [out0];

/// The output summands' labels, in policy order (docs/spec.md §3.11.6).
pub const OUTPUT_LABELS: [&str; 1] = ["c_grant"];

/// The index plus one, in [`OUTPUT_LABELS`], of the output summand fired last; 0:
/// none (docs/spec.md §3.11.6). Process-wide; written only with the feature `firing`.
#[cfg(feature = "firing")]
pub static FIRING: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(0);

/// The label of the output summand fired last, read from any thread; `None`
/// without the feature `firing` or before the first fire (docs/spec.md §3.11.6).
pub fn firing() -> Option<&'static str> {
    #[cfg(feature = "firing")]
    {
        let i = FIRING.load(core::sync::atomic::Ordering::Relaxed);
        return usize::try_from(i).ok().and_then(|i| i.checked_sub(1)).and_then(|i| OUTPUT_LABELS.get(i)).copied();
    }
    #[cfg(not(feature = "firing"))]
    None
}

/// The output loop (docs/spec.md §3.8.3): the first enabled output in policy
/// order, until none is.
fn run_loop(s: &mut S, out: &mut Vec<Action>) -> Result<(), StepError> {
    let mut n: u32 = 0;
    loop {
        let mut fired = false;
        for f in OUTS {
            if f(s, out)? {
                fired = true;
                break;
            }
        }
        if !fired {
            return Ok(());
        }
        refresh(s)?;
        n = n.saturating_add(1);
        if n >= 1 << 24 {
            return Err(StepError::StepLimit);
        }
    }
}

fn state_bytes(s: &S, out: &mut Vec<u8>) {
    {
        let f = &s.phase;
        enc_Phase(f.default_value(), out);
        let e = f.entries();
        codec::len(e.len(), out);
        for (k, v) in e {
            let k = &k;
            enc_Client(k, out);
            enc_Phase(v, out);
        }
    }
    codec::len((&s.queue).len(), out);
    for x1 in (&s.queue).iter() {
        enc_Client(x1, out);
    }
    codec::boolean(*(&s.free), out);
}

/// The stepper of the refined Core (docs/spec.md §3.8.1, §3.8.2, §3.11.2).
#[derive(Debug, Clone)]
pub struct State {
    s: S,
}

impl State {
    pub fn new(config: Config, out: &mut Vec<Action>) -> Result<State, StepError> {
        State::new_with(config, out, |_| {})
    }

    /// The constructor with the initial state changed first, for tests that start
    /// from another initial state.
    #[doc(hidden)]
    pub fn new_with(config: Config, out: &mut Vec<Action>, f: impl FnOnce(&mut S)) -> Result<State, StepError> {
        let mut s = initial(&config)?;
        f(&mut s);
        stepper_init(&mut s)?;
        run_loop(&mut s, out)?;
        Ok(State { s })
    }

    pub fn step(&mut self, event: &Event, out: &mut Vec<Action>) -> Result<(), StepError> {
        let s = &mut self.s;
        match event {
            Event::Ask(a0) => {
                if let Some(env) = match_s0(s, a0)? {
                    fire_s0(s, env)?;
                } else {
                    return Err(StepError::Refused(event.clone()));
                }
            }
            Event::Release(a0) => {
                if let Some(env) = match_s1(s, a0)? {
                    fire_s1(s, env)?;
                } else {
                    return Err(StepError::Refused(event.clone()));
                }
            }
        }
        refresh(s)?;
        run_loop(s, out)
    }

    /// An estimate of the memory the state holds (§3.13.4).
    pub fn bytes(&self) -> usize {
        let mut b = Vec::new();
        state_bytes(&self.s, &mut b);
        b.len()
    }

    /// Every parameter's value, encoded as entries are (for comparing the backends).
    pub fn state_bytes(&self) -> Vec<u8> {
        let mut b = Vec::new();
        state_bytes(&self.s, &mut b);
        b
    }

    /// The state, for tests.
    pub fn state(&self) -> &S {
        &self.s
    }

    /// The members of an index in its order, for tests.
    pub fn index(&self, name: &str) -> Option<Vec<u32>> {
        match name {
            _ => None,
        }
    }
}

